public class Main{public static void main(String[] args)throws Exception{Gson gson=new GsonBuilder().serializeNulls().create();BufferedReader reader=new BufferedReader(new InputStreamReader(System.in));String line;while((line=reader.readLine())!=null){JsonElement input=JsonParser.parseString(line);CwContext cw=new CwContext();IdentityTree cwArgument0=cw.identity_tree(input.getAsJsonObject().get("data"));cw.snapshot_inputs();TreeNode result=new Solution().solve(cwArgument0);cw.check_inputs();System.out.println(gson.toJson(cw.tree_identity(result)));}}}
